package com.floweventbus

import java.lang.reflect.InvocationTargetException
import java.lang.reflect.Method
import java.lang.reflect.Modifier
import java.util.concurrent.ConcurrentHashMap
import kotlin.coroutines.Continuation
import kotlin.coroutines.intrinsics.suspendCoroutineUninterceptedOrReturn

/**
 * One [Subscribe] method. Built by reflection, or by an index generated by `floweventbus-ksp`,
 * whose [invoke] calls the method directly.
 */
class SubscriberMethod(
    val methodName: String,
    val eventType: Class<*>,
    val threadMode: ThreadMode,
    val priority: Int,
    val sticky: Boolean,
    val invoke: suspend (subscriber: Any, event: Any) -> Unit,
)

/**
 * Compile-time list of [Subscribe] methods, generated by `floweventbus-ksp`. Add it with
 * [FlowEventBusBuilder.addIndex] so `register` skips reflection for the classes it covers.
 */
interface SubscriberIndex {
    /** Methods declared by [subscriberClass] itself (not its super classes), or null if the class isn't indexed. */
    fun subscriberMethods(subscriberClass: Class<*>): List<SubscriberMethod>?
}

internal object SubscriberMethodFinder {
    private val cache = ConcurrentHashMap<Class<*>, List<SubscriberMethod>>()

    // ponytail: cache is global, so the first bus to register a class decides index vs reflection for all buses.
    // Both find the same methods; only matters if a class is registered with and without an index.
    fun find(clazz: Class<*>, indexes: List<SubscriberIndex> = emptyList()): List<SubscriberMethod> =
        cache.getOrPut(clazz) { findMethods(clazz, indexes) }

    fun clearCache() = cache.clear()

    private fun findMethods(clazz: Class<*>, indexes: List<SubscriberIndex>): List<SubscriberMethod> {
        val result = ArrayList<SubscriberMethod>()
        val seen = HashSet<String>() // subclass overrides win over super class declarations
        var current: Class<*>? = clazz
        while (current != null && !isSystemClass(current.name)) {
            val declared = indexes.firstNotNullOfOrNull { it.subscriberMethods(current!!) } ?: findUsingReflection(current)
            for (method in declared) {
                if (seen.add(method.methodName + ">" + method.eventType.name)) result += method
            }
            current = current.superclass
        }
        return result
    }

    private fun findUsingReflection(clazz: Class<*>): List<SubscriberMethod> {
        val result = ArrayList<SubscriberMethod>()
        val methods = try {
            clazz.declaredMethods
        } catch (_: Throwable) {
            clazz.methods // e.g. NoClassDefFoundError for optional deps, as in EventBus
        }
        for (method in methods) {
            val annotation = method.getAnnotation(Subscribe::class.java) ?: continue
            if (method.isBridge || method.isSynthetic) continue
            if (Modifier.isStatic(method.modifiers)) {
                throw FlowEventBusException("@Subscribe method must not be static: $method")
            }
            val params = method.parameterTypes
            val isSuspend = params.size == 2 && params[1] == Continuation::class.java
            if (params.size != 1 && !isSuspend) {
                throw FlowEventBusException(
                    "@Subscribe method $method must have exactly 1 parameter (the event), optionally as a suspend fun",
                )
            }
            val eventType = params[0]
            if (eventType.isPrimitive) throw FlowEventBusException("Event type must not be primitive: $method")
            method.isAccessible = true
            result += SubscriberMethod(
                method.name, eventType, annotation.threadMode, annotation.priority, annotation.sticky,
                reflectiveInvoker(method, isSuspend),
            )
        }
        return result
    }

    private fun reflectiveInvoker(method: Method, isSuspend: Boolean): suspend (Any, Any) -> Unit = { target, event ->
        try {
            if (isSuspend) {
                // `suspend fun onX(e: E)` compiles to `onX(E, Continuation): Any?` - pass our continuation.
                suspendCoroutineUninterceptedOrReturn<Any?> { cont -> method.invoke(target, event, cont) }
            } else {
                method.invoke(target, event)
            }
        } catch (e: InvocationTargetException) {
            throw e.targetException
        }
    }

    private fun isSystemClass(name: String) =
        name.startsWith("java.") || name.startsWith("javax.") || name.startsWith("android.") ||
            name.startsWith("androidx.") || name.startsWith("kotlin.") || name.startsWith("kotlinx.")
}
